values.content:
Write a sales proposal.

For: {{ $json.prospectCompany }}{{ $json.prospectContact ? ' — ' + $json.prospectContact : '' }}{{ $json.prospectTitle ? ' (' + $json.prospectTitle + ')' : '' }}
From: {{ $json.companyName }}{{ $json.repName ? ' — ' + $json.repName : '' }}
Product/service: {{ $json.productName }}
Valid until: {{ $json.validUntil || 'not specified' }}
Contract term: {{ $json.contractTerm || 'not specified' }}

Solution description:
{{ $json.solutionDescription }}

Problems addressed:
{{ $json.problemsAddressed.join('\n') || 'infer from solution description' }}

Proposed package: {{ $json.proposedPackage || 'not specified' }}
Pricing: {{ $json.pricing || 'not specified' }}
Implementation timeline: {{ $json.implementationTimeline || 'to be discussed' }}

Key value props:
{{ $json.keyValueProps.join('\n') || 'derive from solution' }}

Case studies:
{{ $json.caseStudies.join('\n') || 'none provided' }}

Call notes / prospect context:
{{ $json.callNotes || 'no call notes provided' }}

Return JSON:
{"proposal":{"executive_summary":"3-4 sentences: prospect's situation and challenge, what we're proposing, expected outcome. Written for the executive who may not have been on discovery calls.","problem_statement":"2-3 paragraphs on the prospect's specific situation and why status quo is costly — use their language from call notes","proposed_solution":"2-3 paragraphs on the solution — outcome-focused, connects directly to the problems named above","why_us":"2-3 sentences on why this company/product specifically suits this prospect — not generic strengths","investment":{"package":"package name and what's included","pricing_summary":"how the investment is structured","roi_framing":"how to frame the value vs cost"},"implementation":{"timeline_overview":"what implementation looks like and how long","what_we_handle":"what the vendor does","what_prospect_handles":"what's required from the prospect's team"},"social_proof":"relevant case studies or customer evidence — use provided case studies","next_steps":[{"step":"","owner":"prospect|vendor","timing":""}],"terms_summary":"contract term, payment terms if known, validity period"},"email_cover_note":"short email to accompany the proposal — 3-4 sentences, personal, references something specific from the relationship"}
